-- =====================================================================
-- 05_consultas_gerenciais.sql — CONSULTAS GERENCIAIS
-- Cada consulta parte de uma PERGUNTA do gerente, usa SQL (SELECT/JOIN)
-- e termina na DECISÃO que a informação apoia.
-- Data de referência: 01/10/2026 (dia seguinte ao último dia da massa).
-- Para usar no dia a dia, troque por: SET @data_ref = CURRENT_DATE;
-- =====================================================================
USE mercado_boturussu;
SET NAMES utf8mb4;
SET @data_ref = DATE('2026-10-01');
SET @ini = DATE('2026-09-01');
SET @fim = DATE('2026-09-30');

-- ---------------------------------------------------------------------
-- G01 — Quais produtos mais faturaram no mês e quanto deixaram de lucro?
-- Origem: PB-16, PB-17; entrevista 8.8 e 8.13 (“se vendem bem, giro e proporção de lucro”).
-- Decisão: o que nunca pode faltar na gôndola e onde a margem compensa.
-- ---------------------------------------------------------------------
SELECT p.nome_produto AS produto,
       c.nome AS categoria,
       ROUND(SUM(r.quantidade_base), 3) AS quantidade_vendida,
       p.unidade_base AS unidade,
       ROUND(SUM(r.valor_item - r.valor_reembolsado), 2) AS faturamento,
       ROUND(SUM(r.custo_total), 2) AS custo_mercadoria,
       ROUND(SUM(r.valor_item - r.valor_reembolsado - r.custo_total), 2) AS lucro_bruto,
       ROUND(100 * SUM(r.valor_item - r.valor_reembolsado - r.custo_total) / SUM(r.valor_item - r.valor_reembolsado), 1) AS margem_pct
FROM vw_item_venda_resultado r
JOIN produto p   ON p.id_produto = r.id_produto
JOIN categoria c ON c.codigo_categoria = p.codigo_categoria
WHERE r.situacao_venda = 'CONCLUIDA' AND DATE(r.data_hora) BETWEEN @ini AND @fim
GROUP BY p.id_produto, p.nome_produto, c.nome, p.unidade_base
ORDER BY faturamento DESC
LIMIT 10;

-- ---------------------------------------------------------------------
-- G02 — Curva ABC: quais produtos concentram 80% do faturamento?
-- Decisão: produtos A recebem prioridade de compra, conferência e preço;
-- produtos C são candidatos a sair do mix ou a ter estoque mínimo menor.
-- ---------------------------------------------------------------------
WITH fat AS (
  SELECT r.id_produto, SUM(r.valor_item - r.valor_reembolsado) AS faturamento
  FROM vw_item_venda_resultado r
  WHERE r.situacao_venda = 'CONCLUIDA' AND DATE(r.data_hora) BETWEEN @ini AND @fim
  GROUP BY r.id_produto
), acum AS (
  SELECT id_produto, faturamento,
         SUM(faturamento) OVER (ORDER BY faturamento DESC, id_produto) / SUM(faturamento) OVER () AS pct_acumulado
  FROM fat
)
SELECT CASE WHEN pct_acumulado <= 0.80 THEN 'A' WHEN pct_acumulado <= 0.95 THEN 'B' ELSE 'C' END AS classe,
       COUNT(*) AS qtd_produtos,
       ROUND(SUM(faturamento), 2) AS faturamento,
       GROUP_CONCAT(p.nome_produto ORDER BY faturamento DESC SEPARATOR '; ') AS produtos
FROM acum JOIN produto p ON p.id_produto = acum.id_produto
GROUP BY classe
ORDER BY classe;

-- ---------------------------------------------------------------------
-- G03 — Quanto vendemos e quanto lucramos por dia? (“lucro do dia”, entrevista 6.20)
-- Decisão: separar movimento de resultado; identificar dias fortes e fracos.
-- ---------------------------------------------------------------------
SELECT DATE(v.data_hora) AS dia,
       ELT(DAYOFWEEK(v.data_hora), 'dom','seg','ter','qua','qui','sex','sáb') AS dia_semana,
       COUNT(*) AS vendas,
       ROUND(SUM(v.valor_total - v.valor_reembolsado), 2) AS faturamento,
       ROUND(AVG(v.valor_total), 2) AS ticket_medio,
       ROUND(SUM(v.lucro_bruto), 2) AS lucro_bruto,
       ROUND(100 * SUM(v.lucro_bruto) / SUM(v.valor_total - v.valor_reembolsado), 1) AS margem_pct
FROM vw_venda_resumo v
WHERE v.situacao = 'CONCLUIDA' AND DATE(v.data_hora) BETWEEN @ini AND @fim
GROUP BY DATE(v.data_hora), dia_semana
ORDER BY dia;

-- ---------------------------------------------------------------------
-- G04 — Quanto entrou em cada forma de pagamento e em cada caixa? (RF-37; PB-10)
-- Decisão: negociar taxas com a operadora; dimensionar troco; ver o peso do fiado.
-- ---------------------------------------------------------------------
SELECT s.numero_caixa AS caixa,
       f.descricao AS forma,
       COUNT(*) AS transacoes,
       ROUND(SUM(pv.valor), 2) AS valor_bruto,
       f.taxa_percentual AS taxa_contratada_pct,
       ROUND(SUM(pv.valor) * f.taxa_percentual / 100, 2) AS custo_estimado_taxa,
       ROUND(100 * SUM(pv.valor) / SUM(SUM(pv.valor)) OVER (PARTITION BY s.numero_caixa), 1) AS pct_no_caixa
FROM pagamento_venda pv
JOIN venda v           ON v.id_venda = pv.id_venda
JOIN sessao_caixa s    ON s.id_sessao = v.id_sessao
JOIN forma_pagamento f ON f.codigo_forma = pv.codigo_forma
WHERE v.situacao = 'CONCLUIDA' AND DATE(v.data_hora) BETWEEN @ini AND @fim
GROUP BY s.numero_caixa, f.codigo_forma, f.descricao, f.taxa_percentual
ORDER BY caixa, valor_bruto DESC;

-- ---------------------------------------------------------------------
-- G05 — LISTA DE VALIDADES: quais lotes vencem nos próximos dias? (prioridade nº 1; RF-17)
-- Usa o prazo de alerta do produto ou, na falta dele, o da categoria (RNF-09).
-- Decisão: promover, conferir na gôndola ou negociar troca antes de vencer.
-- ---------------------------------------------------------------------
SELECT s.id_lote, s.nome_produto AS produto, c.nome AS categoria,
       s.data_validade,
       DATEDIFF(s.data_validade, @data_ref) AS dias_para_vencer,
       COALESCE(p.dias_alerta_validade, c.dias_alerta_validade_padrao) AS prazo_alerta,
       s.quantidade_atual AS saldo, p.unidade_base AS unidade,
       ROUND(s.quantidade_atual * s.custo_unitario, 2) AS valor_em_risco_custo,
       CASE WHEN DATEDIFF(s.data_validade, @data_ref) < 0 THEN 'VENCIDO — retirar'
            WHEN DATEDIFF(s.data_validade, @data_ref) <= 2 THEN 'Promover hoje'
            ELSE 'Acompanhar' END AS acao_sugerida
FROM vw_lote_saldo s
JOIN produto p   ON p.id_produto = s.id_produto
JOIN categoria c ON c.codigo_categoria = p.codigo_categoria
WHERE s.situacao = 'DISPONIVEL' AND s.quantidade_atual > 0 AND s.data_validade IS NOT NULL
  AND DATEDIFF(s.data_validade, @data_ref) <= COALESCE(p.dias_alerta_validade, c.dias_alerta_validade_padrao, 7)
ORDER BY s.data_validade, valor_em_risco_custo DESC;

-- ---------------------------------------------------------------------
-- G06 — O que está abaixo do estoque mínimo, quanto comprar e de quem? (RF-19; PB-02, PB-05)
-- Sugestão = 7 dias da média vendida nos últimos 7 dias + mínimo − estoque atual.
-- Fornecedor sugerido = menor último custo registrado.
-- Decisão: montar o pedido do dia sem conferir gôndola por gôndola.
-- ---------------------------------------------------------------------
WITH media AS (
  SELECT r.id_produto, SUM(r.quantidade_base) / 7 AS media_dia
  FROM vw_item_venda_resultado r
  WHERE r.situacao_venda = 'CONCLUIDA' AND DATE(r.data_hora) BETWEEN DATE_SUB(@data_ref, INTERVAL 7 DAY) AND DATE_SUB(@data_ref, INTERVAL 1 DAY)
  GROUP BY r.id_produto
), melhor AS (
  SELECT u.id_produto, u.id_fornecedor, u.preco_ultima_compra,
         ROW_NUMBER() OVER (PARTITION BY u.id_produto ORDER BY u.preco_ultima_compra) AS rn
  FROM vw_ultimo_custo_fornecedor u
)
SELECT e.nome_produto AS produto, e.estoque_atual, e.estoque_minimo, e.unidade_base AS unidade,
       ROUND(COALESCE(m.media_dia, 0), 2) AS media_vendida_dia,
       ROUND(GREATEST(COALESCE(m.media_dia, 0) * 7 + e.estoque_minimo - e.estoque_atual, 0), 0) AS sugestao_compra,
       f.nome_fantasia AS fornecedor_mais_barato, b.preco_ultima_compra AS ultimo_custo
FROM vw_estoque_produto e
LEFT JOIN media m  ON m.id_produto = e.id_produto
LEFT JOIN melhor b ON b.id_produto = e.id_produto AND b.rn = 1
LEFT JOIN fornecedor f ON f.id_fornecedor = b.id_fornecedor
WHERE e.ativo AND e.abaixo_minimo = 1
ORDER BY (e.estoque_atual / NULLIF(e.estoque_minimo, 0)), produto;

-- ---------------------------------------------------------------------
-- G07 — Quem deve no fiado, quanto e há quanto tempo não paga? (PB-07, PB-08; RF-27)
-- Decisão: cobrar, suspender novas compras ou rever o limite (PO-04).
-- ---------------------------------------------------------------------
SELECT cs.nome AS cliente, COALESCE(cs.apelido, '') AS apelido,
       cs.saldo_devedor, cs.limite_fiado,
       ROUND(100 * cs.saldo_devedor / NULLIF(cs.limite_fiado, 0), 0) AS pct_limite,
       DATE(cs.ultima_compra_fiado) AS ultima_compra,
       DATE(cs.ultimo_abatimento) AS ultimo_pagamento,
       DATEDIFF(@data_ref, COALESCE(cs.ultimo_abatimento, cs.primeira_compra_fiado)) AS dias_sem_pagar,
       CASE WHEN cs.saldo_devedor > cs.limite_fiado THEN 'Acima do limite — suspender'
            WHEN cs.ultimo_abatimento IS NULL AND DATEDIFF(@data_ref, cs.primeira_compra_fiado) > 15 THEN 'Nunca pagou — cobrar'
            WHEN DATEDIFF(@data_ref, COALESCE(cs.ultimo_abatimento, cs.primeira_compra_fiado)) > 15 THEN 'Sem pagar há mais de 15 dias — cobrar'
            WHEN cs.saldo_devedor >= 0.8 * cs.limite_fiado THEN 'Perto do limite'
            ELSE 'Em dia' END AS situacao
FROM vw_cliente_saldo cs
WHERE cs.saldo_devedor > 0
ORDER BY cs.saldo_devedor DESC;

-- ---------------------------------------------------------------------
-- G08 — Quais contas estão em aberto, por vencimento e prioridade? (RF-41; PB-14)
-- Mostra o SALDO em aberto (pagamentos parciais já descontados — RN-38).
-- Decisão: o que pagar primeiro quando o dinheiro não cobre tudo (PO-06).
-- ---------------------------------------------------------------------
SELECT c.data_vencimento, c.prioridade, c.credor, c.descricao, c.categoria_despesa,
       c.valor_original, c.valor_principal_pago, c.saldo_em_aberto, c.situacao,
       CASE WHEN c.data_vencimento < @data_ref THEN CONCAT('VENCIDA há ', DATEDIFF(@data_ref, c.data_vencimento), ' dia(s)')
            WHEN c.data_vencimento <= DATE_ADD(@data_ref, INTERVAL 7 DAY) THEN 'Vence nesta semana'
            ELSE 'A vencer' END AS alerta
FROM vw_conta_pagar_situacao c
WHERE c.situacao IN ('ABERTA','PARCIALMENTE_PAGA')
ORDER BY c.data_vencimento, FIELD(c.prioridade, 'ALTA','MEDIA','BAIXA'), c.saldo_em_aberto DESC;

-- ---------------------------------------------------------------------
-- G09 — PREVISÃO DE DISPONIBILIDADE: vai faltar dinheiro nos próximos 21 dias? (RF-35, RF-36, RN-39)
-- Saldo inicial = saldo realizado (banco + cofre) + dinheiro nas gavetas abertas.
-- Entradas previstas = recebíveis de cartão/Pix/vale ainda não conciliados, pela data
--   prevista de crédito (valor líquido da taxa). Vencidos e não creditados entram no 1º dia.
-- Saídas previstas = saldo em aberto das contas, pelo vencimento (vencidas no 1º dia).
-- Vendas futuras NÃO entram: a previsão é conservadora de propósito.
-- Decisão: o ALERTA pedido pelo gerente (“sim, muito”): antecipar recebíveis, negociar prazo
-- ou escolher, pela prioridade, o que pagar.
-- ---------------------------------------------------------------------
WITH RECURSIVE dias AS (
  SELECT @data_ref AS dia
  UNION ALL
  SELECT DATE_ADD(dia, INTERVAL 1 DAY) FROM dias WHERE dia < DATE_ADD(@data_ref, INTERVAL 20 DAY)
), saldo_ini AS (
  SELECT (SELECT SUM(saldo_atual) FROM vw_conta_financeira_saldo)
       + (SELECT COALESCE(SUM(valor_esperado), 0) FROM vw_sessao_conferencia WHERE situacao = 'ABERTA') AS valor
), entradas AS (
  SELECT GREATEST(data_prevista_credito, @data_ref) AS dia, SUM(valor_liquido_previsto) AS valor
  FROM vw_pagamento_venda_previsao
  WHERE situacao_credito = 'PENDENTE' AND situacao_venda = 'CONCLUIDA'
  GROUP BY GREATEST(data_prevista_credito, @data_ref)
), saidas AS (
  SELECT GREATEST(data_vencimento, @data_ref) AS dia, SUM(saldo_em_aberto) AS valor
  FROM vw_conta_pagar_situacao
  WHERE situacao IN ('ABERTA','PARCIALMENTE_PAGA')
  GROUP BY GREATEST(data_vencimento, @data_ref)
), fluxo AS (
  SELECT d.dia, COALESCE(e.valor, 0) AS entradas, COALESCE(s.valor, 0) AS saidas
  FROM dias d LEFT JOIN entradas e ON e.dia = d.dia LEFT JOIN saidas s ON s.dia = d.dia
)
SELECT f.dia,
       ROUND(f.entradas, 2) AS entradas_previstas,
       ROUND(f.saidas, 2) AS saidas_previstas,
       ROUND((SELECT valor FROM saldo_ini) + SUM(f.entradas - f.saidas) OVER (ORDER BY f.dia), 2) AS saldo_previsto,
       CASE WHEN (SELECT valor FROM saldo_ini) + SUM(f.entradas - f.saidas) OVER (ORDER BY f.dia) < 0
            THEN 'ALERTA: saldo insuficiente' ELSE '' END AS alerta
FROM fluxo f
ORDER BY f.dia;

-- ---------------------------------------------------------------------
-- G10 — Quanto perdemos com vencimento e avaria, e em quais produtos? (RF-40; PB-04)
-- Perda líquida = perdas − reposições recebidas do fornecedor (troca).
-- Decisão: reduzir compra dos produtos que mais vencem; negociar troca; promover antes.
-- ---------------------------------------------------------------------
SELECT p.nome_produto AS produto, c.nome AS categoria,
       ROUND(SUM(CASE WHEN m.tipo = 'PERDA_VENCIMENTO' THEN m.valor_custo ELSE 0 END), 2) AS perda_vencimento,
       ROUND(SUM(CASE WHEN m.tipo = 'PERDA_AVARIA' THEN m.valor_custo ELSE 0 END), 2) AS perda_avaria,
       ROUND(SUM(CASE WHEN m.tipo = 'TROCA_FORNECEDOR' THEN m.valor_custo ELSE 0 END), 2) AS recuperado_na_troca,
       ROUND(SUM(CASE WHEN m.tipo IN ('PERDA_VENCIMENTO','PERDA_AVARIA') THEN m.valor_custo
                      WHEN m.tipo = 'TROCA_FORNECEDOR' THEN -m.valor_custo ELSE 0 END), 2) AS perda_liquida
FROM vw_movimentacao_valorizada m
JOIN produto p   ON p.id_produto = m.id_produto
JOIN categoria c ON c.codigo_categoria = p.codigo_categoria
WHERE m.tipo IN ('PERDA_VENCIMENTO','PERDA_AVARIA','TROCA_FORNECEDOR')
  AND DATE(m.data_hora) BETWEEN @ini AND @fim
GROUP BY p.id_produto, p.nome_produto, c.nome
HAVING perda_vencimento + perda_avaria > 0
ORDER BY perda_liquida DESC;

-- ---------------------------------------------------------------------
-- G11 — De quem comprar? Último custo de cada produto por fornecedor (RF-07; PB-05)
-- Só aparecem produtos comprados de mais de um fornecedor.
-- Decisão: escolher o fornecedor do próximo pedido (ex.: o leite).
-- ---------------------------------------------------------------------
SELECT p.nome_produto AS produto, f.nome_fantasia AS fornecedor,
       u.data_ultima_compra, u.preco_ultima_compra AS custo_unitario,
       ROUND(u.preco_ultima_compra - MIN(u.preco_ultima_compra) OVER (PARTITION BY u.id_produto), 4) AS diferenca_para_o_menor
FROM vw_ultimo_custo_fornecedor u
JOIN produto p    ON p.id_produto = u.id_produto
JOIN fornecedor f ON f.id_fornecedor = u.id_fornecedor
WHERE u.id_produto IN (SELECT id_produto FROM vw_ultimo_custo_fornecedor GROUP BY id_produto HAVING COUNT(*) > 1)
ORDER BY produto, custo_unitario;

-- ---------------------------------------------------------------------
-- G12 — O que foi pedido e ainda não chegou? (RF-10; PB-15)
-- Decisão: cobrar o fornecedor; não pedir de novo o que já está a caminho.
-- ---------------------------------------------------------------------
SELECT ps.id_pedido, ps.razao_social AS fornecedor, DATE(ps.data_hora_pedido) AS data_pedido, ps.situacao,
       x.nome_produto AS produto, x.quantidade_pedida, x.quantidade_recebida, x.quantidade_pendente
FROM vw_pedido_situacao ps
JOIN vw_item_pedido_pendencia x ON x.id_pedido = ps.id_pedido
WHERE ps.situacao IN ('ABERTO','PARCIALMENTE_RECEBIDO') AND x.quantidade_pendente > 0
ORDER BY ps.data_hora_pedido, produto;

-- ---------------------------------------------------------------------
-- G13 — Como foi cada operador no caixa? Vendas, ticket e diferenças de fechamento (PB-11, PB-12)
-- Decisão: treinamento (RNF-04), escala e investigação de diferenças recorrentes.
-- ---------------------------------------------------------------------
SELECT fu.nome AS operador,
       COUNT(DISTINCT v.id_venda) AS vendas,
       ROUND(SUM(v.valor_total), 2) AS faturamento,
       ROUND(AVG(v.valor_total), 2) AS ticket_medio,
       (SELECT COUNT(*) FROM vw_sessao_conferencia sc WHERE sc.id_funcionario_fechamento = fu.id_funcionario) AS sessoes_fechadas,
       (SELECT COALESCE(SUM(sc.diferenca_dinheiro), 0) FROM vw_sessao_conferencia sc WHERE sc.id_funcionario_fechamento = fu.id_funcionario) AS soma_diferencas_dinheiro
FROM vw_venda_resumo v
JOIN funcionario fu ON fu.id_funcionario = v.id_funcionario
WHERE v.situacao = 'CONCLUIDA' AND DATE(v.data_hora) BETWEEN @ini AND @fim
GROUP BY fu.id_funcionario, fu.nome
ORDER BY faturamento DESC;

-- ---------------------------------------------------------------------
-- G14 — Qual a margem de cada setor? (PO-09: margem de 35–40% nos itens comuns)
-- Decisão: rever preços do setor cuja margem real ficou abaixo da política.
-- ---------------------------------------------------------------------
SELECT c.nome AS categoria,
       ROUND(SUM(r.valor_item - r.valor_reembolsado), 2) AS faturamento,
       ROUND(SUM(r.custo_total), 2) AS custo_mercadoria,
       ROUND(100 * SUM(r.valor_item - r.valor_reembolsado - r.custo_total) / SUM(r.valor_item - r.valor_reembolsado), 1) AS margem_sobre_venda_pct,
       ROUND(100 * SUM(r.valor_item - r.valor_reembolsado - r.custo_total) / SUM(r.custo_total), 1) AS markup_sobre_custo_pct
FROM vw_item_venda_resultado r
JOIN produto p   ON p.id_produto = r.id_produto
JOIN categoria c ON c.codigo_categoria = p.codigo_categoria
WHERE r.situacao_venda = 'CONCLUIDA' AND DATE(r.data_hora) BETWEEN @ini AND @fim
GROUP BY c.codigo_categoria, c.nome
ORDER BY margem_sobre_venda_pct;

-- ---------------------------------------------------------------------
-- G15 — Quais produtos giram menos? Dias de cobertura do estoque atual (entrevista 8.9)
-- Cobertura = estoque atual ÷ média diária vendida no mês.
-- Decisão: pedir menos dos itens parados (capital empatado e risco de vencer).
-- ---------------------------------------------------------------------
WITH vendido AS (
  SELECT r.id_produto, SUM(r.quantidade_base) AS qtd_mes
  FROM vw_item_venda_resultado r
  WHERE r.situacao_venda = 'CONCLUIDA' AND DATE(r.data_hora) BETWEEN @ini AND @fim
  GROUP BY r.id_produto
)
SELECT e.nome_produto AS produto, e.estoque_atual, e.unidade_base AS unidade,
       ROUND(COALESCE(v.qtd_mes, 0) / 30, 2) AS media_dia,
       ROUND(e.estoque_atual / NULLIF(COALESCE(v.qtd_mes, 0) / 30, 0), 1) AS dias_de_cobertura,
       ROUND(e.valor_estoque_custo, 2) AS capital_parado
FROM vw_estoque_produto e
LEFT JOIN vendido v ON v.id_produto = e.id_produto
WHERE e.ativo
ORDER BY dias_de_cobertura DESC
LIMIT 10;

-- ---------------------------------------------------------------------
-- G16 — Quanto pagamos de juros por atraso? (entrevista, bloco 2e: o “prejuízo invisível”)
-- Decisão: usar a previsão (G09) para evitar o atraso; renegociar prazos.
-- ---------------------------------------------------------------------
SELECT cp.credor, cp.descricao, cp.data_vencimento, pc.data_pagamento,
       DATEDIFF(pc.data_pagamento, cp.data_vencimento) AS dias_atraso,
       pc.valor_principal, pc.valor_juros_multa
FROM pagamento_conta pc
JOIN conta_pagar cp ON cp.id_conta = pc.id_conta
WHERE pc.valor_juros_multa > 0
ORDER BY pc.data_pagamento;


-- =====================================================================
-- 06_consultas_auditoria.sql — CONSULTAS DE AUDITORIA
-- Objetivo: verificar a QUALIDADE e a CONSISTÊNCIA dos dados.
-- Cada consulta lista as linhas que merecem verificação. Resultado vazio
-- significa que a regra foi respeitada em todo o banco.
-- Regras entre várias linhas/tabelas não cabem em CHECK; por isso são
-- verificadas aqui (decisão D-20 do documento).
-- =====================================================================
USE mercado_boturussu;
SET NAMES utf8mb4;
SET @data_ref = DATE('2026-10-01');

-- ---------------------------------------------------------------------
-- A01 — Vendas concluídas cujo total não bate com a soma dos pagamentos (RN-21)
-- Verifica: venda paga a menos ou a mais (erro de caixa ou de registro).
-- ---------------------------------------------------------------------
SELECT v.id_venda, v.numero_caixa, v.numero_cupom, v.data_hora, v.valor_total, v.total_pago,
       v.total_pago - v.valor_total AS diferenca
FROM vw_venda_resumo v
WHERE v.situacao = 'CONCLUIDA' AND v.total_pago <> v.valor_total;

-- ---------------------------------------------------------------------
-- A02 — Itens de venda concluída sem baixa completa de estoque (RN-17, RN-22)
-- Verifica: item cuja quantidade vendida (na unidade base) não foi toda baixada
-- dos lotes — o estoque e o custo da venda estariam errados.
-- ---------------------------------------------------------------------
SELECT r.id_venda, r.numero_item, p.nome_produto, r.quantidade_base,
       COALESCE(SUM(m.quantidade), 0) AS quantidade_baixada
FROM vw_item_venda_resultado r
JOIN produto p ON p.id_produto = r.id_produto
LEFT JOIN movimentacao_estoque m ON m.id_venda = r.id_venda AND m.numero_item = r.numero_item AND m.tipo = 'SAIDA_VENDA'
WHERE r.situacao_venda = 'CONCLUIDA'
GROUP BY r.id_venda, r.numero_item, p.nome_produto, r.quantidade_base
HAVING quantidade_baixada <> r.quantidade_base;

-- ---------------------------------------------------------------------
-- A03 — Lotes sem movimentação de entrada ou com saldo negativo (RN-16; cardinalidade LOTE 1,N)
-- Verifica: “estoque fantasma” (lote sem origem) e baixa maior que o existente.
-- ---------------------------------------------------------------------
SELECT s.id_lote, s.nome_produto, s.origem, s.quantidade_inicial, s.quantidade_atual,
       CASE WHEN s.quantidade_inicial = 0 THEN 'Lote sem movimentação de entrada'
            ELSE 'Saldo negativo' END AS problema
FROM vw_lote_saldo s
WHERE s.quantidade_inicial = 0 OR s.quantidade_atual < 0;

-- ---------------------------------------------------------------------
-- A04 — Venda fiada sem cliente identificado ou de cliente não autorizado (RN-24, PO-04)
-- Verifica: fiado concedido fora da política. Limitação conhecida: o banco guarda a autorização
-- VIGENTE do cliente, não o histórico dela; se o gerente suspender um cliente, as vendas antigas
-- dele também aparecerão aqui. Por isso a suspensão do crédito é feita pelo limite (OP06).
-- ---------------------------------------------------------------------
SELECT v.id_venda, v.data_hora, c.nome AS cliente, c.autorizado_fiado, pv.valor AS valor_fiado,
       CASE WHEN v.id_cliente IS NULL THEN 'Fiado sem cliente'
            WHEN NOT c.autorizado_fiado THEN 'Cliente não autorizado'
            ELSE 'Verificar' END AS problema
FROM pagamento_venda pv
JOIN venda v ON v.id_venda = pv.id_venda
LEFT JOIN cliente c ON c.id_cliente = v.id_cliente
WHERE pv.codigo_forma = 'FIADO' AND v.situacao = 'CONCLUIDA'
  AND (v.id_cliente IS NULL OR c.autorizado_fiado = FALSE);

-- ---------------------------------------------------------------------
-- A05 — Lotes sem data de validade em produto que controla validade (RN-15)
-- Verifica: lote que nunca aparecerá na lista de validades (prioridade nº 1).
-- ---------------------------------------------------------------------
SELECT s.id_lote, s.nome_produto, s.origem, s.data_entrada, s.quantidade_atual
FROM vw_lote_saldo s
JOIN produto p ON p.id_produto = s.id_produto
WHERE p.controla_validade = TRUE AND s.data_validade IS NULL;

-- ---------------------------------------------------------------------
-- A06 — Sessões fechadas com diferença de caixa (dinheiro ou maquininhas) sem justificativa (RN-30)
-- Verifica: sobra/falta que ninguém explicou.
-- ---------------------------------------------------------------------
SELECT sc.id_sessao, sc.numero_caixa, sc.data_hora_abertura, f.nome AS fechada_por,
       sc.valor_esperado, sc.valor_contado, sc.diferenca_dinheiro,
       sc.total_eletronico_registrado, sc.total_maquininhas_informado, sc.diferenca_eletronica
FROM vw_sessao_conferencia sc
JOIN funcionario f ON f.id_funcionario = sc.id_funcionario_fechamento
WHERE sc.situacao = 'FECHADA'
  AND (sc.diferenca_dinheiro <> 0 OR sc.diferenca_eletronica <> 0)
  AND sc.justificativa_diferenca IS NULL;

-- ---------------------------------------------------------------------
-- A07 — Transações de cartão/Pix/vale não creditadas após a data prevista (RN-36)
-- Verifica: dinheiro que a operadora deveria ter pago e não pagou (conciliação).
-- Tolerância de 1 dia útil após a data prevista.
-- ---------------------------------------------------------------------
SELECT p.id_venda, p.numero_pagamento, p.codigo_forma, DATE(p.data_venda) AS data_venda, p.nsu_autorizacao,
       p.valor, p.data_prevista_credito, DATEDIFF(@data_ref, p.data_prevista_credito) AS dias_de_atraso
FROM vw_pagamento_venda_previsao p
WHERE p.situacao_credito = 'PENDENTE' AND p.situacao_venda = 'CONCLUIDA'
  AND p.data_prevista_credito < DATE_SUB(@data_ref, INTERVAL 1 DAY);

-- ---------------------------------------------------------------------
-- A08 — Créditos conciliados com divergência de valor ou taxa (RN-36)
-- Verifica: repasse menor que o previsto (taxa acima da contratada ou transação faltante).
-- ---------------------------------------------------------------------
SELECT c.id_movimento_fin, c.data_movimento, c.documento_referencia, c.qtd_transacoes,
       c.bruto_previsto, c.valor_bruto, c.taxa_prevista, c.valor_taxa,
       ROUND(100 * c.valor_taxa / c.valor_bruto, 2) AS taxa_cobrada_pct,
       c.diferenca_conciliacao
FROM vw_conciliacao c
WHERE c.situacao_conciliacao <> 'CONCILIADO';

-- ---------------------------------------------------------------------
-- A09 — Contas a pagar: pagamento acima do valor original ou conta vencida sem quitação (RN-38)
-- Verifica: erro de lançamento (pagou a mais) e obrigações em atraso (juros correndo).
-- ---------------------------------------------------------------------
SELECT c.id_conta, c.credor, c.descricao, c.data_vencimento, c.valor_original, c.valor_principal_pago,
       c.saldo_em_aberto, c.situacao,
       CASE WHEN c.valor_principal_pago > c.valor_original THEN 'Pago acima do valor'
            ELSE CONCAT('Vencida há ', DATEDIFF(@data_ref, c.data_vencimento), ' dia(s)') END AS problema
FROM vw_conta_pagar_situacao c
WHERE c.valor_principal_pago > c.valor_original
   OR (c.situacao IN ('ABERTA','PARCIALMENTE_PAGA') AND c.data_vencimento < @data_ref);

-- ---------------------------------------------------------------------
-- A10 — Lotes vencidos ainda disponíveis para venda (RN-19; fluxo F3)
-- Verifica: a rotina diária de validade não foi executada para esse lote.
-- ---------------------------------------------------------------------
SELECT s.id_lote, s.nome_produto, s.data_validade, DATEDIFF(@data_ref, s.data_validade) AS dias_vencido,
       s.quantidade_atual
FROM vw_lote_saldo s
WHERE s.situacao = 'DISPONIVEL' AND s.quantidade_atual > 0 AND s.data_validade < @data_ref;

-- ---------------------------------------------------------------------
-- A11 — Lotes de ajuste automático aguardando conferência física (RN-40)
-- Verifica: venda feita com saldo do sistema insuficiente que ainda não foi conferida.
-- ---------------------------------------------------------------------
SELECT s.id_lote, s.nome_produto, s.data_entrada, s.quantidade_inicial, s.custo_unitario, s.quantidade_atual
FROM vw_lote_saldo s
WHERE s.pendente_conferencia = TRUE;

-- ---------------------------------------------------------------------
-- A12 — Devoluções que somam mais do que foi vendido no item (RN-28)
-- Verifica: devolução duplicada ou digitada errada.
-- ---------------------------------------------------------------------
SELECT iv.id_venda, iv.numero_item, iv.quantidade AS vendida, SUM(d.quantidade_devolvida) AS devolvida
FROM devolucao d
JOIN item_venda iv ON iv.id_venda = d.id_venda AND iv.numero_item = d.numero_item
GROUP BY iv.id_venda, iv.numero_item, iv.quantidade
HAVING SUM(d.quantidade_devolvida) > iv.quantidade;

-- ---------------------------------------------------------------------
-- A13 — Operações sensíveis feitas por quem não tinha a permissão (RN-07, RN-23, PO-11, PO-13, RNF-01)
-- Verifica: o controle de acesso foi contornado (ex.: senha emprestada). A permissão é conferida
-- NA DATA DA OPERAÇÃO (concessão e revogação), por isso revogar hoje não “suja” o passado.
-- ---------------------------------------------------------------------
SELECT 'Desconto autorizado' AS operacao, iv.id_venda AS referencia, f.nome AS funcionario, v.data_hora AS quando,
       'AUTORIZAR_DESCONTO' AS permissao_exigida
FROM item_venda iv JOIN venda v ON v.id_venda = iv.id_venda
JOIN funcionario f ON f.id_funcionario = iv.id_funcionario_autorizador
WHERE iv.id_funcionario_autorizador IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM funcionario_permissao fp WHERE fp.id_funcionario = iv.id_funcionario_autorizador
                  AND fp.codigo_permissao = 'AUTORIZAR_DESCONTO' AND fp.data_concessao <= DATE(v.data_hora)
                  AND (fp.data_revogacao IS NULL OR fp.data_revogacao > DATE(v.data_hora)))
UNION ALL
SELECT 'Alteração de preço', hp.id_historico, f.nome, hp.data_hora, 'ALTERAR_PRECO'
FROM historico_preco hp JOIN funcionario f ON f.id_funcionario = hp.id_funcionario
WHERE NOT EXISTS (SELECT 1 FROM funcionario_permissao fp WHERE fp.id_funcionario = hp.id_funcionario
                  AND fp.codigo_permissao = 'ALTERAR_PRECO' AND fp.data_concessao <= DATE(hp.data_hora)
                  AND (fp.data_revogacao IS NULL OR fp.data_revogacao > DATE(hp.data_hora)))
UNION ALL
SELECT 'Abertura de caixa', s.id_sessao, f.nome, s.data_hora_abertura, 'OPERAR_CAIXA'
FROM sessao_caixa s JOIN funcionario f ON f.id_funcionario = s.id_funcionario_abertura
WHERE NOT EXISTS (SELECT 1 FROM funcionario_permissao fp WHERE fp.id_funcionario = s.id_funcionario_abertura
                  AND fp.codigo_permissao = 'OPERAR_CAIXA' AND fp.data_concessao <= DATE(s.data_hora_abertura)
                  AND (fp.data_revogacao IS NULL OR fp.data_revogacao > DATE(s.data_hora_abertura)))
UNION ALL
SELECT 'Devolução autorizada', d.id_devolucao, f.nome, d.data_hora, 'AUTORIZAR_DEVOLUCAO'
FROM devolucao d JOIN funcionario f ON f.id_funcionario = d.id_funcionario
WHERE NOT EXISTS (SELECT 1 FROM funcionario_permissao fp WHERE fp.id_funcionario = d.id_funcionario
                  AND fp.codigo_permissao = 'AUTORIZAR_DEVOLUCAO' AND fp.data_concessao <= DATE(d.data_hora)
                  AND (fp.data_revogacao IS NULL OR fp.data_revogacao > DATE(d.data_hora)))
UNION ALL
SELECT 'Registro de perda', m.id_movimentacao, f.nome, m.data_hora, 'REGISTRAR_PERDA'
FROM movimentacao_estoque m JOIN funcionario f ON f.id_funcionario = m.id_funcionario
WHERE m.tipo IN ('PERDA_VENCIMENTO','PERDA_AVARIA')
  AND NOT EXISTS (SELECT 1 FROM funcionario_permissao fp WHERE fp.id_funcionario = m.id_funcionario
                  AND fp.codigo_permissao = 'REGISTRAR_PERDA' AND fp.data_concessao <= DATE(m.data_hora)
                  AND (fp.data_revogacao IS NULL OR fp.data_revogacao > DATE(m.data_hora)));

-- ---------------------------------------------------------------------
-- A14 — Preço vigente diferente do último preço registrado no histórico (RN-06)
-- Verifica: preço alterado direto na embalagem, sem deixar histórico.
-- ---------------------------------------------------------------------
SELECT e.id_embalagem, p.nome_produto, e.descricao, e.preco_venda AS preco_vigente, h.preco_novo AS ultimo_preco_historico
FROM embalagem e
JOIN produto p ON p.id_produto = e.id_produto
JOIN historico_preco h ON h.id_embalagem = e.id_embalagem
WHERE h.data_hora = (SELECT MAX(h2.data_hora) FROM historico_preco h2 WHERE h2.id_embalagem = e.id_embalagem)
  AND h.preco_novo <> e.preco_venda;

-- ---------------------------------------------------------------------
-- A15 — Itens vendidos abaixo do custo (preço praticado menor que o custo dos lotes baixados)
-- Verifica: erro de preço, desconto exagerado ou custo de lote digitado errado.
-- ---------------------------------------------------------------------
SELECT r.id_venda, r.numero_item, p.nome_produto, r.data_hora, r.quantidade_base,
       ROUND(r.valor_item / r.quantidade_base, 2) AS preco_liquido_unitario,
       ROUND(r.custo_baixado / r.quantidade_base, 2) AS custo_unitario,
       ROUND(r.valor_item - r.custo_baixado, 2) AS prejuizo_no_item
FROM vw_item_venda_resultado r
JOIN produto p ON p.id_produto = r.id_produto
WHERE r.situacao_venda = 'CONCLUIDA' AND r.valor_item < r.custo_baixado
ORDER BY prejuizo_no_item;

-- ---------------------------------------------------------------------
-- A16 — Baixa de venda feita em lote de outro produto (RN-17)
-- Verifica: incoerência que a FK sozinha não impede (o lote é de um produto,
-- o item é de uma embalagem — o produto dos dois precisa ser o mesmo).
-- ---------------------------------------------------------------------
SELECT m.id_movimentacao, m.id_venda, m.numero_item, l.id_produto AS produto_do_lote, e.id_produto AS produto_vendido
FROM movimentacao_estoque m
JOIN lote l ON l.id_lote = m.id_lote
JOIN item_venda iv ON iv.id_venda = m.id_venda AND iv.numero_item = m.numero_item
JOIN embalagem e ON e.id_embalagem = iv.id_embalagem
WHERE m.tipo = 'SAIDA_VENDA' AND l.id_produto <> e.id_produto;

-- ---------------------------------------------------------------------
-- A17 — Nota de um fornecedor atendendo pedido de outro fornecedor (RN-11, RN-12)
-- Verifica: vínculo indevido entre recebimento e pedido.
-- ---------------------------------------------------------------------
SELECT ir.id_recebimento, ir.numero_item_nota, r.id_fornecedor AS fornecedor_da_nota, pc.id_fornecedor AS fornecedor_do_pedido
FROM item_recebimento ir
JOIN recebimento r ON r.id_recebimento = ir.id_recebimento
JOIN pedido_compra pc ON pc.id_pedido = ir.id_pedido
WHERE r.id_fornecedor <> pc.id_fornecedor;

-- ---------------------------------------------------------------------
-- A18 — Linha de nota cuja soma dos lotes difere da quantidade aceita (RN-14)
-- Verifica: estoque gerado a mais ou a menos que o aceito na conferência.
-- ---------------------------------------------------------------------
SELECT ir.id_recebimento, ir.numero_item_nota, p.nome_produto, ir.quantidade_aceita,
       COALESCE(SUM(s.quantidade_inicial), 0) AS soma_dos_lotes
FROM item_recebimento ir
JOIN produto p ON p.id_produto = ir.id_produto
LEFT JOIN vw_lote_saldo s ON s.id_recebimento = ir.id_recebimento AND s.numero_item_nota = ir.numero_item_nota
GROUP BY ir.id_recebimento, ir.numero_item_nota, p.nome_produto, ir.quantidade_aceita
HAVING soma_dos_lotes <> ir.quantidade_aceita;

-- ---------------------------------------------------------------------
-- A19 — Fundo de troco: abertura diferente do que ficou na gaveta no fechamento anterior do mesmo caixa
-- Verifica: dinheiro que “sumiu” ou “apareceu” entre duas sessões.
-- ---------------------------------------------------------------------
WITH ordem AS (
  SELECT sc.id_sessao, sc.numero_caixa, sc.data_hora_abertura, sc.valor_inicial,
         sc.valor_contado - sc.recolhido_fechamento AS ficou_na_gaveta,
         LAG(sc.valor_contado - sc.recolhido_fechamento) OVER (PARTITION BY sc.numero_caixa ORDER BY sc.data_hora_abertura) AS deixado_antes
  FROM vw_sessao_conferencia sc
)
SELECT id_sessao, numero_caixa, data_hora_abertura, deixado_antes, valor_inicial, valor_inicial - deixado_antes AS diferenca
FROM ordem
WHERE deixado_antes IS NOT NULL AND valor_inicial <> deixado_antes;

-- ---------------------------------------------------------------------
-- A20 — Venda baixada de lote que já estava vencido na data da venda (RN-17, RN-19, PO-07)
-- Verifica: venda de produto vencido (risco sanitário e de reclamação).
-- ---------------------------------------------------------------------
SELECT m.id_venda, m.numero_item, l.id_lote, p.nome_produto, l.data_validade, DATE(m.data_hora) AS data_venda
FROM movimentacao_estoque m
JOIN lote l ON l.id_lote = m.id_lote
JOIN produto p ON p.id_produto = l.id_produto
WHERE m.tipo = 'SAIDA_VENDA' AND l.data_validade IS NOT NULL AND l.data_validade < DATE(m.data_hora);

-- ---------------------------------------------------------------------
-- A21 — Cardinalidades mínimas 1 que a FK não consegue garantir (R02, R06, R12, R16, R27, R37)
-- Verifica: “cabeçalho sem filho obrigatório”. A FK garante que o filho aponta para um pai existente,
-- mas não que todo pai tenha ao menos um filho. Ex.: produto ativo sem embalagem ativa (não pode ser
-- vendido — RN-03), pedido sem item, nota sem linha, venda sem item, devolução sem movimento de estoque.
-- ---------------------------------------------------------------------
SELECT 'Produto ativo sem embalagem ativa (R02, RN-03)' AS problema, p.id_produto AS referencia
FROM produto p
WHERE p.ativo AND NOT EXISTS (SELECT 1 FROM embalagem e WHERE e.id_produto = p.id_produto AND e.ativa)
UNION ALL
SELECT 'Lote sem nenhuma movimentação (R06, RN-16)', l.id_lote
FROM lote l WHERE NOT EXISTS (SELECT 1 FROM movimentacao_estoque m WHERE m.id_lote = l.id_lote)
UNION ALL
SELECT 'Pedido sem itens (R12, RN-10)', pc.id_pedido
FROM pedido_compra pc WHERE NOT EXISTS (SELECT 1 FROM item_pedido ip WHERE ip.id_pedido = pc.id_pedido)
UNION ALL
SELECT 'Recebimento sem linhas de nota (R16, RN-13)', r.id_recebimento
FROM recebimento r WHERE NOT EXISTS (SELECT 1 FROM item_recebimento ir WHERE ir.id_recebimento = r.id_recebimento)
UNION ALL
SELECT 'Venda sem itens (R27, RN-21)', v.id_venda
FROM venda v WHERE NOT EXISTS (SELECT 1 FROM item_venda iv WHERE iv.id_venda = v.id_venda)
UNION ALL
SELECT 'Devolução sem retorno ao estoque (R37, RN-28)', d.id_devolucao
FROM devolucao d WHERE NOT EXISTS (SELECT 1 FROM movimentacao_estoque m WHERE m.id_devolucao = d.id_devolucao);

-- ---------------------------------------------------------------------
-- A22 — Custo do lote diferente da sua origem (RN-19, RN-22; redundância controlada)
-- Verifica: o custo copiado para o lote na entrada continua igual à fonte — linha da nota
-- (valor unitário ÷ fator de conversão) ou, na reposição de troca, o custo do lote trocado.
-- É a contrapartida de guardar o custo no lote (necessário para lotes sem nota).
-- ---------------------------------------------------------------------
SELECT l.id_lote, l.origem, l.custo_unitario AS custo_no_lote,
       ROUND(ir.valor_unitario_nota / ir.fator_conversao_compra, 4) AS custo_na_origem
FROM lote l
JOIN item_recebimento ir ON ir.id_recebimento = l.id_recebimento AND ir.numero_item_nota = l.numero_item_nota
WHERE l.custo_unitario <> ROUND(ir.valor_unitario_nota / ir.fator_conversao_compra, 4)
UNION ALL
SELECT l.id_lote, l.origem, l.custo_unitario, r.custo_unitario
FROM lote l JOIN lote r ON r.id_lote = l.id_lote_reposto
WHERE l.custo_unitario <> r.custo_unitario;


-- =====================================================================
-- 07_operacoes_update_delete.sql — UPDATE e DELETE em processos reais
-- Cenário: manhã de 01/10/2026. O gerente rodou as consultas gerenciais (05)
-- e de auditoria (06) e agora age sobre o que elas mostraram.
-- Cada operação: (1) SELECT do “antes”, (2) alteração dentro de transação,
-- (3) SELECT do “depois”. Nenhum identificador é fixo no código: as linhas
-- são localizadas pelas mesmas regras das consultas, como faria o sistema.
-- Registros operacionais NÃO são apagados (RNF-06, PO-12); DELETE só é
-- usado em dados cadastrais ou planejados que ainda não geraram efeito (OP07, OP08).
-- =====================================================================
USE mercado_boturussu;
SET NAMES utf8mb4;
SET @data_ref = DATE('2026-10-01');

-- ---------------------------------------------------------------------
-- OP01 (UPDATE) — Conferência do lote de ajuste automático do Guaraná (achado A11, RN-40)
-- A contagem no depósito encontrou 10 garrafas além do sistema. Registra-se
-- a entrada do ajuste (INSERT na movimentação) e o lote deixa de estar pendente.
-- ---------------------------------------------------------------------
SET @lote_pend = (SELECT l.id_lote FROM lote l JOIN produto p ON p.id_produto = l.id_produto
                  WHERE l.pendente_conferencia = TRUE AND p.nome_produto LIKE 'Refrigerante Guaraná%' LIMIT 1);
SELECT 'OP01 antes' AS etapa, id_lote, nome_produto, pendente_conferencia, quantidade_atual, data_validade
FROM vw_lote_saldo WHERE id_lote = @lote_pend;

START TRANSACTION;
VALUES (@lote_pend, 1, '2026-10-01 07:40:00', 'AJUSTE_INVENTARIO_ENTRADA', 10,
        'Conferência do ajuste RN-40: 10 garrafas encontradas no depósito');
UPDATE lote
   SET pendente_conferencia = FALSE,
       data_validade = '2027-01-20'          -- validade lida nas garrafas durante a conferência
 WHERE id_lote = @lote_pend;
COMMIT;

SELECT 'OP01 depois' AS etapa, id_lote, nome_produto, pendente_conferencia, quantidade_atual, data_validade
FROM vw_lote_saldo WHERE id_lote = @lote_pend;

-- ---------------------------------------------------------------------
-- OP02 (UPDATE) — Lote de margarina sem validade (achado A05, RN-15)
-- A validade foi lida na embalagem e lançada. O lote passa a aparecer na lista de validades.
-- ---------------------------------------------------------------------
SET @lote_sem_val = (SELECT l.id_lote FROM lote l JOIN produto p ON p.id_produto = l.id_produto
                     WHERE p.controla_validade = TRUE AND l.data_validade IS NULL
                       AND p.nome_produto LIKE 'Margarina%' LIMIT 1);
SELECT 'OP02 antes' AS etapa, id_lote, data_validade FROM lote WHERE id_lote = @lote_sem_val;
UPDATE lote SET data_validade = '2026-10-04' WHERE id_lote = @lote_sem_val;
SELECT 'OP02 depois' AS etapa, id_lote, data_validade FROM lote WHERE id_lote = @lote_sem_val;

-- ---------------------------------------------------------------------
-- OP03 (UPDATE) — Justificar as diferenças de caixa sem explicação (achado A06, RN-30)
-- ---------------------------------------------------------------------
SELECT 'OP03 antes' AS etapa, id_sessao, numero_caixa, diferenca_dinheiro, diferenca_eletronica, justificativa_diferenca
FROM vw_sessao_conferencia
WHERE situacao = 'FECHADA' AND (diferenca_dinheiro <> 0 OR diferenca_eletronica <> 0) AND justificativa_diferenca IS NULL;

START TRANSACTION;
UPDATE sessao_caixa s
JOIN vw_sessao_conferencia sc ON sc.id_sessao = s.id_sessao
   SET s.justificativa_diferenca = 'Sobra de R$ 1,00: moeda deixada por cliente; conferido pelo gerente em 01/10'
 WHERE sc.diferenca_dinheiro = 1.00 AND s.justificativa_diferenca IS NULL;
UPDATE sessao_caixa s
JOIN vw_sessao_conferencia sc ON sc.id_sessao = s.id_sessao
   SET s.justificativa_diferenca = 'Venda de R$ 15,00 passada no débito e registrada como dinheiro; corrigido no relatório'
 WHERE sc.diferenca_eletronica = 15.00 AND s.justificativa_diferenca IS NULL;
COMMIT;

SELECT 'OP03 depois' AS etapa, COUNT(*) AS sessoes_sem_justificativa
FROM vw_sessao_conferencia
WHERE situacao = 'FECHADA' AND (diferenca_dinheiro <> 0 OR diferenca_eletronica <> 0) AND justificativa_diferenca IS NULL;

-- ---------------------------------------------------------------------
-- OP04 (INSERT + efeito no saldo) — Quitar a parcela vencida do frigorífico com juros (achado A09, RN-38)
-- O pagamento sai do banco: primeiro o movimento financeiro, depois o pagamento que aponta para ele.
-- ---------------------------------------------------------------------
SET @conta_vencida = (SELECT id_conta FROM vw_conta_pagar_situacao
                      WHERE situacao = 'ABERTA' AND data_vencimento < @data_ref AND credor LIKE 'Frigorífico%'
                      ORDER BY data_vencimento LIMIT 1);
SELECT 'OP04 antes' AS etapa, id_conta, credor, data_vencimento, valor_original, saldo_em_aberto, situacao
FROM vw_conta_pagar_situacao WHERE id_conta = @conta_vencida;

START TRANSACTION;
SET @saldo = (SELECT saldo_em_aberto FROM vw_conta_pagar_situacao WHERE id_conta = @conta_vencida);
SET @juros = ROUND(@saldo * (0.02 + 0.00033 * DATEDIFF(@data_ref,
                  (SELECT data_vencimento FROM conta_pagar WHERE id_conta = @conta_vencida))), 2);
                                  valor_bruto, valor_taxa, documento_referencia)
VALUES ((SELECT id_conta_financeira FROM conta_financeira WHERE tipo = 'CONTA_BANCARIA' LIMIT 1), 1, @data_ref,
        'DEBITO', 'PAGAMENTO_CONTA', @saldo + @juros, 0, CONCAT('PGTO-', LPAD(@conta_vencida, 4, '0'), '-ATRASO'));
SET @mov = LAST_INSERT_ID();
                             valor_principal, valor_juros_multa, valor_desconto, observacao)
VALUES (@conta_vencida,
        (SELECT COALESCE(MAX(pc.numero_pagamento), 0) + 1 FROM pagamento_conta pc WHERE pc.id_conta = @conta_vencida),
        1, @mov, @data_ref, @saldo, @juros, 0, 'Quitação com atraso (multa 2% + juros diários)');
COMMIT;

SELECT 'OP04 depois' AS etapa, id_conta, valor_original, valor_principal_pago, encargos_pagos, saldo_em_aberto, situacao
FROM vw_conta_pagar_situacao WHERE id_conta = @conta_vencida;

-- ---------------------------------------------------------------------
-- OP05 (UPDATE com histórico) — Reajuste do leite pela política de preço (RN-05, RN-06, RN-07)
-- Toda alteração de preço grava o histórico NA MESMA TRANSAÇÃO: ou as duas coisas acontecem, ou nenhuma.
-- ---------------------------------------------------------------------
SET @emb_leite = (SELECT e.id_embalagem FROM embalagem e JOIN produto p ON p.id_produto = e.id_produto
                  WHERE p.nome_produto LIKE 'Leite Integral%' AND e.fator_conversao = 1 LIMIT 1);
SELECT 'OP05 antes' AS etapa, id_embalagem, descricao, preco_venda FROM embalagem WHERE id_embalagem = @emb_leite;

START TRANSACTION;
SELECT id_embalagem, 2, '2026-10-01 08:00:00', preco_venda, 6.49, 'REAJUSTE_FORNECEDOR'
FROM embalagem WHERE id_embalagem = @emb_leite;
UPDATE embalagem SET preco_venda = 6.49 WHERE id_embalagem = @emb_leite;
COMMIT;

SELECT 'OP05 depois' AS etapa, e.id_embalagem, e.preco_venda, h.preco_anterior, h.preco_novo, h.motivo, h.data_hora
FROM embalagem e JOIN historico_preco h ON h.id_embalagem = e.id_embalagem
WHERE e.id_embalagem = @emb_leite ORDER BY h.data_hora DESC LIMIT 1;

-- ---------------------------------------------------------------------
-- OP06 (UPDATE) — Gerente reduz o limite de quem nunca pagou o fiado (achado G07, PO-04)
-- Chico comprou fiado, nunca abateu nada e já usa 99% do limite. O gerente baixa o limite para
-- R$ 100,00: a dívida continua registrada, mas novas compras fiadas ficam bloqueadas até ele pagar
-- parte do saldo (RN-25). A autorização não é retirada para não perder o histórico de crédito.
-- ---------------------------------------------------------------------
SELECT 'OP06 antes' AS etapa, id_cliente, nome, apelido, limite_fiado, saldo_devedor, ultimo_abatimento
FROM vw_cliente_saldo WHERE apelido = 'Chico';
UPDATE cliente SET limite_fiado = 100.00 WHERE apelido = 'Chico' AND autorizado_fiado = TRUE;
SELECT 'OP06 depois' AS etapa, id_cliente, nome, apelido, limite_fiado, saldo_devedor,
       CASE WHEN saldo_devedor > limite_fiado THEN 'Acima do limite — novas compras fiadas bloqueadas' ELSE 'Dentro do limite' END AS efeito
FROM vw_cliente_saldo WHERE apelido = 'Chico';

-- ---------------------------------------------------------------------
-- OP07 (DELETE) — Vendedor saiu da distribuidora: remover o contato e cadastrar o novo
-- Contato é dado cadastral (não é histórico operacional), por isso pode ser excluído.
-- ---------------------------------------------------------------------
SELECT 'OP07 antes' AS etapa, cf.* FROM contato_fornecedor cf JOIN fornecedor f ON f.id_fornecedor = cf.id_fornecedor
WHERE f.nome_fantasia = 'Bebidas Leste';
START TRANSACTION;
DELETE cf FROM contato_fornecedor cf JOIN fornecedor f ON f.id_fornecedor = cf.id_fornecedor
WHERE f.nome_fantasia = 'Bebidas Leste' AND cf.nome = 'Fábio Martins';
SELECT id_fornecedor, 3, 'Renata Siqueira', '11940010011', TRUE FROM fornecedor WHERE nome_fantasia = 'Bebidas Leste';
COMMIT;
SELECT 'OP07 depois' AS etapa, cf.* FROM contato_fornecedor cf JOIN fornecedor f ON f.id_fornecedor = cf.id_fornecedor
WHERE f.nome_fantasia = 'Bebidas Leste';

-- ---------------------------------------------------------------------
-- OP08 (DELETE) — Retirar do pedido em aberto um item que ainda não chegou (RN-11)
-- Motivo: o vendedor avisou que está sem Sabão em Pó Omo; o item sai do pedido para ser comprado de outro fornecedor.
-- Só é permitido porque nenhuma linha de nota atende esse item: a FK
-- fk_ir_item_pedido bloquearia a exclusão de item já recebido.
-- ---------------------------------------------------------------------
SET @ped_aberto = (SELECT id_pedido FROM vw_pedido_situacao WHERE situacao = 'ABERTO' ORDER BY data_hora_pedido DESC LIMIT 1);
SET @prod_retirar = (SELECT x.id_produto FROM vw_item_pedido_pendencia x WHERE x.id_pedido = @ped_aberto
                     AND x.quantidade_recebida = 0 AND x.nome_produto LIKE 'Sabão em Pó%' LIMIT 1);
SELECT 'OP08 antes' AS etapa, id_pedido, nome_produto, quantidade_pedida, quantidade_recebida
FROM vw_item_pedido_pendencia WHERE id_pedido = @ped_aberto;
DELETE FROM item_pedido
 WHERE id_pedido = @ped_aberto AND id_produto = @prod_retirar
   AND NOT EXISTS (SELECT 1 FROM item_recebimento ir WHERE ir.id_pedido = @ped_aberto AND ir.id_produto = @prod_retirar);
SELECT 'OP08 depois' AS etapa, id_pedido, nome_produto, quantidade_pedida, quantidade_recebida
FROM vw_item_pedido_pendencia WHERE id_pedido = @ped_aberto;

-- ---------------------------------------------------------------------
-- OP09 (UPDATE, não DELETE) — Revogar permissão: após o preço errado de 17/09 (achado A15), o gerente
-- decidiu que apenas ele e Mariana alteram preço. A linha NÃO é apagada: grava-se a data de revogação.
-- Motivo (decisão D-24): se a linha fosse excluída, a auditoria A13 passaria a acusar como
-- “sem permissão” as alterações que Rafael fez quando ainda podia — o passado ficaria errado.
-- ---------------------------------------------------------------------
SELECT 'OP09 antes' AS etapa, f.nome, fp.codigo_permissao, fp.data_concessao, fp.data_revogacao
FROM funcionario_permissao fp JOIN funcionario f ON f.id_funcionario = fp.id_funcionario
WHERE fp.codigo_permissao = 'ALTERAR_PRECO';
UPDATE funcionario_permissao fp JOIN funcionario f ON f.id_funcionario = fp.id_funcionario
   SET fp.data_revogacao = @data_ref
 WHERE fp.codigo_permissao = 'ALTERAR_PRECO' AND f.login = 'rafael.dias' AND fp.data_revogacao IS NULL;
SELECT 'OP09 depois' AS etapa, f.nome, fp.codigo_permissao, fp.data_concessao, fp.data_revogacao,
       CASE WHEN fp.data_revogacao IS NULL THEN 'vigente' ELSE 'revogada' END AS situacao
FROM funcionario_permissao fp JOIN funcionario f ON f.id_funcionario = fp.id_funcionario
WHERE fp.codigo_permissao = 'ALTERAR_PRECO';

-- ---------------------------------------------------------------------
-- Reexecução das auditorias afetadas: comprova que as ações resolveram os achados
-- ---------------------------------------------------------------------
SELECT 'A05 depois' AS auditoria, COUNT(*) AS ocorrencias FROM vw_lote_saldo s JOIN produto p ON p.id_produto = s.id_produto
WHERE p.controla_validade = TRUE AND s.data_validade IS NULL AND s.pendente_conferencia = FALSE
UNION ALL
SELECT 'A06 depois', COUNT(*) FROM vw_sessao_conferencia
WHERE situacao = 'FECHADA' AND (diferenca_dinheiro <> 0 OR diferenca_eletronica <> 0) AND justificativa_diferenca IS NULL
UNION ALL
SELECT 'A09 depois (vencidas sem nenhum pagamento)', COUNT(*) FROM vw_conta_pagar_situacao
WHERE situacao = 'ABERTA' AND data_vencimento < @data_ref
UNION ALL
SELECT 'A11 depois', COUNT(*) FROM lote WHERE pendente_conferencia = TRUE;
